<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;

$token=trim((string)($_GET['t']??''));
$pdo=Database::connection();
$s=$pdo->prepare('SELECT t.*,e.name event_name,e.starts_at,e.venue,e.address,e.banner_url,b.name batch_name,c.name customer_name,c.email customer_email,tn.name tenant_name,tn.primary_color,tn.secondary_color FROM tickets t JOIN events e ON e.id=t.event_id JOIN ticket_batches b ON b.id=t.batch_id JOIN tenants tn ON tn.id=t.tenant_id LEFT JOIN customers c ON c.id=t.customer_id WHERE t.qr_token=? LIMIT 1');
$s->execute([$token]);$ticket=$s->fetch();if(!$ticket){http_response_code(404);exit('Ingresso não encontrado.');}
$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($ticket['primary_color']??''))?(string)$ticket['primary_color']:'#6d4aff';$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($ticket['secondary_color']??''))?(string)$ticket['secondary_color']:'#8b5cf6';
$statusLabel=match((string)$ticket['status']){'paid'=>'Válido','checked_in'=>'Utilizado','reserved'=>'Reservado','cancelled'=>'Cancelado',default=>ucfirst((string)$ticket['status'])};
$qrSvg=null;if(in_array($ticket['status'],['paid','checked_in'],true)&&class_exists('Endroid\\QrCode\\QrCode')){try{$url=rtrim((string)env('APP_URL',''),'/').'/ingresso.php?t='.rawurlencode($token);$qr=new \Endroid\QrCode\QrCode(data:$url,size:320,margin:12);$writer=new \Endroid\QrCode\Writer\SvgWriter();$qrSvg=$writer->write($qr)->getString();}catch(Throwable){$qrSvg=null;}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title><?= Security::e($ticket['event_name']) ?> — Ingresso</title><link rel="stylesheet" href="<?= Security::e(app_url('/assets/app.css')) ?>?v=92ticket2"><style>
:root{--ticket-primary:<?= Security::e($primary) ?>;--ticket-secondary:<?= Security::e($secondary) ?>}.ticket-page{margin:0;min-height:100vh;background:linear-gradient(145deg,#f2effc,#f8f8fb);color:#242431;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.ticket-shell{width:min(520px,100%);margin:auto;padding:25px 16px 55px}.ticket-brand{text-align:center;margin-bottom:15px;font-size:13px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:#6b5e96}.ticket-brand span{color:var(--ticket-primary)}.real-ticket{background:#fff;border:1px solid #e7e3f1;border-radius:28px;overflow:hidden;box-shadow:0 24px 70px rgba(44,31,84,.14)}.ticket-cover{position:relative;min-height:190px;padding:26px;color:#fff;background:linear-gradient(135deg,var(--ticket-primary),var(--ticket-secondary));background-size:cover;background-position:center}.ticket-cover:after{content:"";position:absolute;inset:0;background:linear-gradient(135deg,rgba(30,18,65,.78),rgba(30,18,65,.18))}.ticket-cover>*{position:relative;z-index:1}.ticket-cover small{font-size:10px;font-weight:850;text-transform:uppercase;letter-spacing:.1em;opacity:.85}.ticket-cover h1{font-size:30px;line-height:1.05;margin:10px 0 9px}.ticket-cover p{font-size:12px;line-height:1.45;margin:0;opacity:.9}.ticket-body{padding:22px 24px 26px}.ticket-meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px}.ticket-meta div{background:#f8f7fb;border-radius:12px;padding:11px}.ticket-meta span{display:block;color:#8a8795;font-size:9px;text-transform:uppercase;font-weight:850;letter-spacing:.05em}.ticket-meta strong{display:block;margin-top:4px;font-size:12px}.ticket-holder{border-top:1px dashed #dcd7e8;border-bottom:1px dashed #dcd7e8;padding:16px 0;margin:6px 0 18px}.ticket-holder span{display:block;color:#8a8795;font-size:9px;text-transform:uppercase;font-weight:850}.ticket-holder strong{display:block;font-size:17px;margin-top:3px}.ticket-status{display:flex;justify-content:center;margin-bottom:15px}.ticket-status b{padding:7px 11px;border-radius:999px;background:#e9f8f1;color:#147a52;font-size:10px}.ticket-status.used b{background:#eef0f4;color:#686979}.ticket-status.reserved b{background:#fff4dc;color:#a86800}.ticket-status.invalid b{background:#fff0f2;color:#c03d4e}.qr{text-align:center}.qr svg{width:min(290px,100%);height:auto;background:#fff;border-radius:18px;padding:8px}.ticket-code{text-align:center;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:15px;font-weight:850;letter-spacing:.07em;word-break:break-all;margin:12px 0 5px}.ticket-note{text-align:center;color:#858291;font-size:10px;line-height:1.45;margin:0}.ticket-cut{height:20px;position:relative}.ticket-cut:before,.ticket-cut:after{content:"";position:absolute;top:0;width:20px;height:20px;border-radius:50%;background:#f4f2fa}.ticket-cut:before{left:-10px}.ticket-cut:after{right:-10px}.ticket-actions{text-align:center;margin-top:16px}.ticket-actions button{background:#fff;border:1px solid #ddd8e8;border-radius:11px;padding:9px 13px;font-weight:800;color:#625975}@media(max-width:420px){.ticket-shell{padding:12px 10px 40px}.ticket-cover{min-height:170px;padding:21px}.ticket-cover h1{font-size:25px}.ticket-body{padding:18px}.ticket-meta{grid-template-columns:1fr 1fr}}
</style></head><body class="ticket-page"><main class="ticket-shell"><div class="ticket-brand">EventMenu <span>Premium</span></div><article class="real-ticket"><section class="ticket-cover"<?php if(!empty($ticket['banner_url'])):?> style="background-image:url('<?= Security::e($ticket['banner_url']) ?>')"<?php endif;?>><small><?= Security::e($ticket['tenant_name']) ?></small><h1><?= Security::e($ticket['event_name']) ?></h1><p><?= Security::e(date('d/m/Y \à\s H:i',strtotime($ticket['starts_at']))) ?><br><?= Security::e($ticket['venue']?:'Local a confirmar') ?><?php if(!empty($ticket['address'])):?><br><?= Security::e($ticket['address']) ?><?php endif;?></p></section><div class="ticket-cut"></div><section class="ticket-body"><div class="ticket-meta"><div><span>Ingresso</span><strong><?= Security::e($ticket['batch_name']) ?></strong></div><div><span>Código</span><strong><?= Security::e($ticket['code']) ?></strong></div></div><div class="ticket-holder"><span>Titular</span><strong><?= Security::e($ticket['customer_name']??'Ingresso') ?></strong><?php if(!empty($ticket['customer_email'])):?><small><?= Security::e($ticket['customer_email']) ?></small><?php endif;?></div><div class="ticket-status <?= Security::e($ticket['status']==='checked_in'?'used':($ticket['status']==='reserved'?'reserved':($ticket['status']==='paid'?'':'invalid'))) ?>"><b><?= Security::e($statusLabel) ?></b></div><?php if(in_array($ticket['status'],['paid','checked_in'],true)):?><?php if($qrSvg):?><div class="qr"><?= $qrSvg ?></div><?php else:?><div class="alert error">QR temporariamente indisponível. Use o código do ingresso na entrada.</div><?php endif;?><div class="ticket-code"><?= Security::e($ticket['code']) ?></div><p class="ticket-note"><?= $ticket['status']==='checked_in'?'Este ingresso já foi utilizado.':'Apresente este QR na entrada. O ingresso só pode ser validado uma vez.' ?></p><?php elseif($ticket['status']==='reserved'):?><div class="alert">Reserva aguardando pagamento até <?= Security::e($ticket['reserved_until']??'') ?>.</div><?php else:?><div class="alert error">Este ingresso não está válido para entrada.</div><?php endif;?></section></article><div class="ticket-actions"><button type="button" onclick="window.print()">Imprimir ingresso</button></div></main></body></html>
